INSERT INTO `sourcelead`.`EMAIL_SCENARIO` (`SCENARIO_NAME`, `ENTITY_TYPE`, `UNIQUE_SCENARIO_NAME`, `DESCRIPTION`, `SUBJECT`, `TEMPLATE_TYPE`, `SIGNATURE`, `BODY`, `IS_TEMPLATE_MODIFIED`, `CREATED_BY`, `ORG_CODE`, `LOCATION_CODE`) VALUES ('OffBoardingProcessApplicantTermination', 'Email', 'OffBoardingProcessApplicantTermination', 'Send mail to OffBoardingProcessApplicantTermination', 'Termination from {{OffBoardingProcessApplicantTermination.companyName}}','sourcelead','Best Regards,\n{{OffBoardingProcessApplicantTermination.loginUser}}','Dear {{OffBoardingProcessApplicantTermination.applicantName}},\n\nWe regret to inform you that your employment with {{OffBoardingProcessApplicantTermination.companyName}} is being terminated,\neffective date on {{OffBoardingProcessApplicantTermination.effectiveDate}} and end date on {{OffBoardingProcessApplicantTermination.endDate}} Your termination is the result\noffboard reason: {{OffBoardingProcessApplicantTermination.offboardReason}}.\nThank you for your time and service at {{OffBoardingProcessApplicantTermination.companyName}}. If you have future questions or concerns please revert back.\nPlease click here to complete the offboarding process.\n\n{{OffBoardingProcessApplicantTermination.loginLink}}', 'N', 'SLADMIN', 'sourceLead.com','in.sourceLead.com');